"""
    Extract H&E stain vectors and intensities from PLISM-wsi tiles 

    The script performs the following steps:
    * read pre-computed image metrics (e.g. saturation, entropy, colorfulness) generated by compute_stats.py
    * apply thresholds to select suitable tiles
    * peform stain unmixing
    * export the results
    * generate visual analysis reports for each tile

    __author__ = "Lydia Schönpflug, lydia.schoenpflug[at]unibas[dot]ch"
    __creation__ = "2025"
"""

import os
import pprint
from glob import glob
from pathlib import Path
from typing import Any, Dict

import config as _c
import numpy as np
import pandas as pd
import utils.utils_global as _ub
from PIL import Image
from tqdm import tqdm
from utils.utils_stainUnmix import staining_unmix


def get_intensity(image: np.ndarray, stain_source: np.ndarray, thresh: float = 0.1) -> Dict[str, float]:
    max_intensity_vect = np.amax(image, axis=(0, 1))
    max_intensity_vect = max_intensity_vect.astype(np.float32)
    max_intensity_vect = np.maximum(max_intensity_vect, 1)
    mat_proj_inverse = np.linalg.inv(stain_source)
    image_OD = np.maximum(1, image)
    image_OD = image_OD / max_intensity_vect
    image_OD = -1.0 * np.log(image_OD)
    image_proj = np.matmul(image_OD, mat_proj_inverse.T)

    # -- Track median (above min threshold) of H and E channels
    channels = {0: "H", 1: "E"}
    stats = {}
    masks = {}
    for ch, label in channels.items():
        mask = image_proj[..., ch] > thresh
        masks[label] = mask
        values = image_proj[mask, ch]
        if values.size == 0:
            stats[f"{label}_median"] = np.nan
            stats[f"{label}_90th"] = np.nan
            stats[f"{label}_95th"] = np.nan
            stats[f"{label}_99th"] = np.nan
            stats[f"{label}_max"] = np.nan
            continue
        stats[f"{label}_median"] = float(np.median(values))
        stats[f"{label}_90th"] = float(np.percentile(values, 90))
        stats[f"{label}_95th"] = float(np.percentile(values, 95))
        stats[f"{label}_99th"] = float(np.percentile(values, 95))
        stats[f"{label}_max"] = float(np.max(values))
    return stats


def get_thresholds(df: pd.DataFrame) -> Dict[str, float]:
    """Return dataset-specific thresholds based on percentiles."""
    return {
        "frac_sat": df["frac_sat"].quantile(0.3),
        "entropy": df["entropy"].quantile(0.3),
        "colorfulness": df["colorfulness"].quantile(0.3),
        "frac_blue": df["frac_blue"].quantile(0.3),
        "hue_circular_var": df["hue_circular_var"].quantile(0.2),
        "lap_var": df["lap_var"].quantile(0.2),
        "frac_redyellow": df["frac_redyellow"].quantile(0.4),
        "frac_green": df["frac_green"].quantile(0.4),
    }


def apply_thresholds(row: Dict[str, Any], thresholds: Dict[str, float]) -> bool:
    """Return tiles that pass all thresholds with debug prints."""
    checks = {
        "frac_sat": row["frac_sat"] >= thresholds["frac_sat"],
        "entropy": row["entropy"] >= thresholds["entropy"],
        "colorfulness": row["colorfulness"] >= thresholds["colorfulness"],
        "frac_blue": row["frac_blue"] >= thresholds["frac_blue"],
        "hue_circular_var": row["hue_circular_var"] >= thresholds["hue_circular_var"],
        "lap_var": row["lap_var"] >= thresholds["lap_var"],
        "frac_redyellow": row["frac_redyellow"] <= thresholds["frac_redyellow"],
        "frac_green": row["frac_green"] <= thresholds["frac_green"],
    }

    for key, passed in checks.items():
        status = "PASS" if passed else "FAIL"
        print(f"{row.get('fp','[no fp]')}: {key} = {row[key]:.4f} {status} (threshold={thresholds[key]:.4f})")

    return all(checks.values())


if __name__ == "__main__":
    ### CONFIGURATION ###
    data_dir = ""  # <--- Path to PLISM-wsi dataset
    stats_dir = ""  # <--- Path to pre-computed img metrics
    output_dir = ""  # <--- Path to store unmixing results and analysis reports
    redo: bool = False  # <--- Force re-processing of tiles
    #####################

    df = pd.read_csv(f"{data_dir}/PLISM_wsi_en.csv")
    search_dir = f"{data_dir}/*/*.png"
    tile_fps = sorted(glob(search_dir))
    params = {k: v for k, v in vars(_c).items() if not k.startswith("__")}
    print("Configuration:")
    pprint.pprint(params)

    thresholds = {}
    stats_dfs = {}
    for stain, stain_df in df.groupby("stain"):
        for device, subset_df in stain_df.groupby("device"):
            csv_path = f"{stats_dir}/metrics_{stain}_{device}.csv"
            stats_dfs[f"{stain}_{device}"] = pd.read_csv(csv_path)
            thresholds[f"{stain}_{device}"] = get_thresholds(stats_dfs[f"{stain}_{device}"])
            print(f"\n### {stain} | {device}")
            print("Thresholds:", thresholds[f"{stain}_{device}"])

    wsi_tile_ids = df["path"]
    tile_ids = [Path(fp).stem for fp in tile_fps]
    print(len(tile_ids), len(wsi_tile_ids), len(np.unique(tile_ids)))
    intensity_stats = []
    with tqdm(tile_fps, desc="Unmix") as pbar:
        for fp in pbar:
            image_filename = Path(fp).stem
            stain, device = fp.split("/")[-3], fp.split("/")[-2]
            pbar.set_postfix(tile_id=str(image_filename))

            with Image.open(fp) as img_pil:
                image = np.array(img_pil)
                image = image[:, :, :3]
                image = image.astype(np.uint8)

            if os.path.exists(f"{output_dir}/analysis_reports/{image_filename}_analysisReport.png") or not redo:
                continue
            else:
                df = stats_dfs[f"{stain}_{device}"]
                row = df[df["fp"] == fp].iloc[0].to_dict()
                if not apply_thresholds(row, thresholds[f"{stain}_{device}"]):
                    if os.path.exists(f"{output_dir}/analysis_reports/{image_filename}_analysisReport.png"):
                        os.remove(f"{output_dir}/analysis_reports/{image_filename}_analysisReport.png")
                    if os.path.exists(f"{output_dir}/npz/{stain}_{device}/{image_filename}.npz"):
                        os.remove(f"{output_dir}/npz/{stain}_{device}/{image_filename}.npz")
                    continue

                """ 2) APPLY STAIN UNMIXING ALGORITHM
                """
                result = staining_unmix(
                    image,
                    _c.patch_subsampling_factor,
                    _c.background_cutoff_percentile,
                    _c.foreground_cutoff,
                    _c.scatterplot_smoothing_kernel,
                    _c.scatterplot_smoothing_stdev,
                    80 if stain[-1] == "H" else 95,
                    95 if stain[-1] == "H" else 80,
                    _c.angular_shift,
                )
                if result is None:
                    continue

                MAE_score, report_dict, max_intensity_vect, HE_max_val, stainMatrix = result
                print(f">> Image sucessfully unmixed (reconstruction.MAE={MAE_score})")

                """ 3) EXPORT STAIN DATA
                """
                stainMatrix_inv = None
                if np.any(stainMatrix):
                    stainMatrix_inv = np.linalg.inv(stainMatrix)

                export_dict = {
                    "maxIntensityVect": max_intensity_vect.astype(np.float32),
                    "maxStainIntensityVect": HE_max_val.astype(np.float32),
                    "stainMatrix": stainMatrix.astype(np.float32),
                    "stainMatrixInv": stainMatrix_inv.astype(np.float32),
                }
                intensity_stat = get_intensity(image, stainMatrix)
                export_dict = {**export_dict, **intensity_stat}
                intensity_stats.append(
                    {
                        "image_filename": image_filename,
                        "stain": stain,
                        "device": device,
                        **intensity_stat,
                    }
                )

                if not os.path.isdir(f"{output_dir}/npz/{stain}_{device}"):
                    os.makedirs(f"{output_dir}/npz/{stain}_{device}", exist_ok=True)
                path_target = f"{output_dir}/npz/{stain}_{device}/{image_filename}.npz"
                np.savez(path_target, **export_dict)
                print(f">> Stain data exported at: {path_target}")

                """ 4) GENERATE AN ANALYSIS REPORT
                """
                report_image_list = []
                for k, v in report_dict.items():
                    _text = _ub.text2np(k, 14)
                    img_c = _ub.concat_vertical([v, _text])
                    report_image_list.append(img_c)

                if not os.path.isdir(f"{output_dir}/analysis_reports/{stain}_{device}"):
                    os.makedirs(f"{output_dir}/analysis_reports/{stain}_{device}", exist_ok=True)
                path_target = f"{output_dir}/analysis_reports/{stain}_{device}/{image_filename}_analysisReport.png"
                image_out = _ub.concat_horizontal(report_image_list)
                image_out = image_out.astype(np.uint8)
                Image.fromarray(image_out).save(path_target)
                print(f">> Analysis report exported at: {path_target}")

                pd.DataFrame(intensity_stats).to_csv(f"{output_dir}/intensity_stats.csv", index=False)
